{
  "root": "main_stack",
  "state": {
    "coreSafetyFeatures": [
      {
        "feature": "Advanced Airbag System",
        "description": "Includes 10 airbags, featuring front airbags, front knee airbags, front side airbags, rear side airbags, and side curtain airbags with rollover sensor."
      },
      {
        "feature": "Advanced Compatibility Engineering™ (ACE™) Body Structure",
        "description": "Honda's proprietary body design enhances occupant protection and crash compatibility in frontal collisions."
      },
      {
        "feature": "Anti-lock Braking System (ABS)",
        "description": "With Electronic Brake Distribution (EBD) and Brake Assist."
      },
      {
        "feature": "Vehicle Stability Assist™ (VSA®)",
        "description": "With Traction Control."
      },
      {
        "feature": "Multi-Angle Rearview Camera",
        "description": "With dynamic guidelines."
      }
    ],
    "hondaSensingFeatures": [
      { "feature": "Collision Mitigation Braking System™ (CMBS™)" },
      { "feature": "Road Departure Mitigation System (RDM)" },
      { "feature": "Adaptive Cruise Control (ACC) with Low-Speed Follow" },
      { "feature": "Lane Keeping Assist System (LKAS)" },
      { "feature": "Forward Collision Warning (FCW)" },
      { "feature": "Lane Departure Warning (LDW)" },
      { "feature": "Traffic Jam Assist" },
      { "feature": "Traffic Sign Recognition System (TSR)" },
      { "feature": "Blind Spot Information System (BSI) with Cross Traffic Monitor" },
      { "feature": "Auto High-Beam Headlights" },
      { "feature": "Front and Rear Parking Sensors" },
      { "feature": "Low-Speed Braking Control" }
    ],
    "iihsRatings": [
      { "category": "TOP SAFETY PICK+", "rating": "(highest award for 2023)" },
      {
        "category": "Crashworthiness",
        "rating": "Good (all categories including small overlap front, moderate overlap front, side, roof strength, head restraints & seats)"
      },
      { "category": "Headlights (EX-L trim)", "rating": "Good" },
      { "category": "Front crash prevention (vehicle-to-vehicle)", "rating": "Superior" },
      { "category": "Front crash prevention (vehicle-to-pedestrian, day)", "rating": "Superior" }
    ],
    "nhtsaRatings": [
      { "category": "5-Star Overall Safety Rating", "rating": "(highest possible rating)" },
      { "category": "Overall Frontal Crash", "rating": "5 Stars" },
      { "category": "Frontal Barrier - Driver", "rating": "5 Stars" },
      { "category": "Frontal Barrier - Passenger", "rating": "5 Stars" },
      { "category": "Overall Side Crash", "rating": "5 Stars" },
      { "category": "Side Barrier", "rating": "5 Stars" },
      { "category": "Side Pole Crash", "rating": "5 Stars" },
      { "category": "Rollover", "rating": "4 Stars" }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_stack",
        "intro_text",
        "divider_1",
        "core_safety_heading_stack",
        "core_safety_intro_text",
        "core_safety_table",
        "divider_2",
        "honda_sensing_heading_stack",
        "honda_sensing_intro_text",
        "honda_sensing_table",
        "divider_3",
        "crash_test_heading",
        "crash_test_intro_text",
        "iihs_heading",
        "iihs_table",
        "nhtsa_heading",
        "nhtsa_table",
        "divider_4",
        "quick_actions_heading",
        "honda_button",
        "iihs_button",
        "nhtsa_button"
      ]
    },
    "title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "car_icon",
        "main_title"
      ]
    },
    "car_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000712_01_1_car-front.svg"
      },
      "children": []
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "2023 Honda CR-V EX-L Safety Features Overview",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "The 2023 Honda CR-V EX-L trim offers a comprehensive suite of safety features, combining advanced passive restraints with the Honda Sensing® driver-assist technologies to enhance protection and driver awareness. It has also received top safety ratings from independent organizations."
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "core_safety_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "shield_icon_1",
        "core_safety_heading"
      ]
    },
    "shield_icon_1": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000712_01_2_shield-fill-check.svg"
      },
      "children": []
    },
    "core_safety_heading": {
      "type": "Text",
      "props": {
        "text": "Core Safety Systems and Passive Protection",
        "variant": "h3"
      },
      "children": []
    },
    "core_safety_intro_text": {
      "type": "Text",
      "props": {
        "text": "The CR-V EX-L is equipped with a robust set of passive safety features designed to protect occupants in the event of a collision."
      },
      "children": []
    },
    "core_safety_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "feature",
            "label": "Feature"
          },
          {
            "key": "description",
            "label": "Description"
          }
        ],
        "statePath": "/coreSafetyFeatures",
        "domain": "generic",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "honda_sensing_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "shield_icon_2",
        "honda_sensing_heading"
      ]
    },
    "shield_icon_2": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000712_01_2_shield-fill-check.svg"
      },
      "children": []
    },
    "honda_sensing_heading": {
      "type": "Text",
      "props": {
        "text": "Honda Sensing® Driver-Assist Technologies",
        "variant": "h3"
      },
      "children": []
    },
    "honda_sensing_intro_text": {
      "type": "Text",
      "props": {
        "text": "The EX-L trim comes standard with the full Honda Sensing® suite, providing a range of active safety and driver-assistive features:"
      },
      "children": []
    },
    "honda_sensing_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "feature",
            "label": "Feature"
          }
        ],
        "statePath": "/hondaSensingFeatures",
        "domain": "generic",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "divider_3": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "crash_test_heading": {
      "type": "Text",
      "props": {
        "text": "Independent Crash Test Ratings",
        "variant": "h3"
      },
      "children": []
    },
    "crash_test_intro_text": {
      "type": "Text",
      "props": {
        "text": "The 2023 Honda CR-V has earned high marks from leading independent safety organizations."
      },
      "children": []
    },
    "iihs_heading": {
      "type": "Text",
      "props": {
        "text": "IIHS (Insurance Institute for Highway Safety):",
        "variant": "body"
      },
      "children": []
    },
    "iihs_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "category",
            "label": "Category"
          },
          {
            "key": "rating",
            "label": "Rating"
          }
        ],
        "statePath": "/iihsRatings",
        "domain": "status",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "nhtsa_heading": {
      "type": "Text",
      "props": {
        "text": "NHTSA (National Highway Traffic Safety Administration):",
        "variant": "body"
      },
      "children": []
    },
    "nhtsa_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "category",
            "label": "Category"
          },
          {
            "key": "rating",
            "label": "Rating"
          }
        ],
        "statePath": "/nhtsaRatings",
        "domain": "status",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "divider_4": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "honda_button": {
      "type": "Button",
      "props": {
        "label": "2023 CR-V Features"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://automobiles.honda.com/cr-v"
          }
        }
      },
      "children": []
    },
    "iihs_button": {
      "type": "Button",
      "props": {
        "label": "IIHS CR-V Ratings"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.iihs.org/ratings/vehicle/honda/cr-v-4-door-suv/2023"
          }
        }
      },
      "children": []
    },
    "nhtsa_button": {
      "type": "Button",
      "props": {
        "label": "NHTSA CR-V Ratings"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.nhtsa.gov/vehicle/2023/HONDA/CR-V/SUV/FWD"
          }
        }
      },
      "children": []
    }
  }
}
